#include "native.hpp"
using R=bitset<128>;
struct Block { vector<Gate> gs; vector<U> ids; unordered_map<U,int> ix; };
struct Local {unsigned char op,a,b;};
static pair<vector<R>,R> transform(const vector<Local>& g,int n){vector<R> r(n);R c;for(int i=0;i<n;i++)r[i].set(i);for(auto s:g){int a=s.a,b=s.b;if(s.op==17)c.flip(a);else if(s.op==33){r[b]^=r[a];c[b]=c[b]^c[a];}else{swap(r[a],r[b]);bool z=c[a];c[a]=c[b];c[b]=z;}}return {r,c};}
static vector<Local> synth(vector<R> r,R c,int n,bool rev){vector<Local> out;vector<char> active(n,1);for(int k=0;k<n;k++){int col=rev?n-1-k:k,p=col;if(!r[p][col]){int cost=129;p=-1;for(int i=0;i<n;i++)if(active[i]&&r[i][col]&&(int)r[i].count()<cost){p=i;cost=r[i].count();}assert(p>=0);}if(p!=col){swap(r[p],r[col]);out.push_back({34,(unsigned char)p,(unsigned char)col});}for(int i=0;i<n;i++)if(i!=col&&r[i][col]){r[i]^=r[col];out.push_back({33,(unsigned char)col,(unsigned char)i});}active[col]=0;}for(int i=0;i<n;i++){R v;v.set(i);assert(r[i]==v);}reverse(out.begin(),out.end());for(int i=0;i<n;i++)if(c[i])out.push_back({17,(unsigned char)i,0});return out;}
int main(int argc,char**argv){Reader r(argv[1]);Writer w(r,r.B);Block b;unordered_map<string,vector<Local>> cache;L count=0,removed=0,hit=0,checked=0;auto flush=[&](){if(b.gs.empty())return;if(b.gs.size()<4){for(auto g:b.gs)w.put(g);}else{vector<Local> g;string key;key.reserve(b.gs.size()*3);for(auto s:b.gs){Local v{(unsigned char)(s.op&127),(unsigned char)b.ix.at(s.a),(unsigned char)((s.op&127)==17?0:b.ix.at(s.b))};g.push_back(v);key.push_back(v.op);key.push_back(v.a);key.push_back(v.b);}int n=b.ids.size();vector<Local> best;auto it=cache.find(key);if(it!=cache.end()){best=it->second;hit++;}else{auto m=transform(g,n);best=g;for(bool rev:{false,true}){auto s=synth(m.first,m.second,n,rev);if(s.size()<best.size())best=move(s);}assert(transform(best,n)==m);checked++;if(cache.size()<100000)cache.emplace(move(key),best);}if(best.size()<g.size()){removed+=g.size()-best.size();count++;}for(auto s:best){Gate t{};t.op=(b.gs[0].op&128)|s.op;t.cond=b.gs[0].cond;t.a=b.ids[s.a];if(s.op!=17)t.b=b.ids[s.b];w.put(t);}}b.gs.clear();b.ids.clear();b.ix.clear();};
for(L i=0;i<r.counts[0];i++){auto g=r.read(i);int o=g.op&127;bool affine=o==17||o==33||o==34;if(!affine){flush();w.put(g);continue;}if(!b.gs.empty()&&((b.gs[0].op&128)!=(g.op&128)||b.gs[0].cond!=g.cond||b.gs.size()>=192||b.ids.size()>=126))flush();for(U q:{g.a,g.b}){if(o==17&&q==g.b&&q!=g.a)continue;if(!b.ix.count(q)){b.ix[q]=b.ids.size();b.ids.push_back(q);}}b.gs.push_back(g);}flush();w.write(argv[2]);cout<<"old "<<r.counts[0]<<" new "<<w.ops.size()<<" changed "<<count<<" removed "<<removed<<" unique_checked "<<checked<<" cache_hits "<<hit<<endl;}
